pug:
table.row.brad-full.white-bg
    tr
        td.wrapper.last.offset-by-one
            table.ten.columns
                tr
                    td.text-pad-small.pb44.pt44
                        p.middle-title.pb32 {{ text_1 }}
                        .first-block
                            .inside-padding
                                p.fat-text.mw-1 {{ text_2 }}
                        .second-block
                            .inside-padding
                                p.fat-text {{ text_3 }}
                        .h-8 &nbsp;
                        .third-block
                            .inside-padding
                                p.fat-text {{ text_4 }}
                        .fourth-block
                            .inside-padding
                                p.fat-text {{ text_5 }}
                        .h-8 &nbsp;
                        .fiveth-block
                            .inside-padding
                                p.fat-text {{ text_6 }}
                        .sixth-block
                            .inside-padding
                                p.fat-text.mw-3 {{ text_7 }}

styl:
.brad-full { border-radius: 32px !important; }
.white-bg { background-color: #fff; }
.middle-title { font-family: Helvetica !important;
